  1→package cmd
  2→
  3→import (
  4→	"bufio"
  5→	"fmt"
  6→	"os"
  7→	"strings"
  8→
  9→	"github.com/spf13/cobra"
 10→
 11→	"github.com/plane-cli/plane-cli/internal/config"
 12→)
 13→
 14→func newConfigCmd() *cobra.Command {
 15→	cmd := &cobra.Command{
 16→		Use:   "config",
 17→		Short: "Manage CLI configuration",
 18→	}
 19→
 20→	cmd.AddCommand(newConfigInitCmd())
 21→	cmd.AddCommand(newConfigSetCmd())
 22→	cmd.AddCommand(newConfigGetCmd())
 23→	cmd.AddCommand(newConfigListCmd())
 24→
 25→	return cmd
 26→}
 27→
 28→func newConfigInitCmd() *cobra.Command {
 29→	return &cobra.Command{
 30→		Use:   "init",
 31→		Short: "Initialize configuration interactively",
 32→		RunE: func(cmd *cobra.Command, args []string) error {
 33→			reader := bufio.NewReader(os.Stdin)
 34→
 35→			// Base URL (required for self-hosted)
 36→			fmt.Print("Plane instance URL (e.g., https://plane.example.com): ")
 37→			baseURL, _ := reader.ReadString('\n')
 38→			baseURL = strings.TrimSpace(baseURL)
 39→			if baseURL == "" {
 40→				return fmt.Errorf("base URL is required for self-hosted instances")
 41→			}
 42→
 43→			// API Key
 44→			fmt.Print("API key: ")
 45→			apiKey, _ := reader.ReadString('\n')
 46→			apiKey = strings.TrimSpace(apiKey)
 47→			if apiKey == "" {
 48→				return fmt.Errorf("API key is required")
 49→			}
 50→
 51→			// Workspace (optional)
 52→			fmt.Print("Default workspace slug (optional): ")
 53→			ws, _ := reader.ReadString('\n')
 54→			ws = strings.TrimSpace(ws)
 55→
 56→			// Project (optional)
 57→			fmt.Print("Default project ID (optional): ")
 58→			proj, _ := reader.ReadString('\n')
 59→			proj = strings.TrimSpace(proj)
 60→
 61→			cfg := &config.Config{
 62→				BaseURL:   strings.TrimRight(baseURL, "/"),
 63→				APIKey:    apiKey,
 64→				Workspace: ws,
 65→				Project:   proj,
 66→				Format:    "json",
 67→			}
 68→
 69→			if err := config.Save(cfg); err != nil {
 70→				return fmt.Errorf("saving config: %w", err)
 71→			}
 72→
 73→			fmt.Printf("Configuration saved to %s\n", config.FilePath())
 74→			return nil
 75→		},
 76→	}
 77→}
 78→
 79→func newConfigSetCmd() *cobra.Command {
 80→	return &cobra.Command{
 81→		Use:   "set <key> <value>",
 82→		Short: "Set a config value",
 83→		Long:  "Valid keys: " + strings.Join(config.ValidKeys(), ", "),
 84→		Args:  cobra.ExactArgs(2),
 85→		RunE: func(cmd *cobra.Command, args []string) error {
 86→			if err := config.Set(args[0], args[1]); err != nil {
 87→				return err
 88→			}
 89→			fmt.Printf("Set %s = %s\n", args[0], args[1])
 90→			return nil
 91→		},
 92→	}
 93→}
 94→
 95→func newConfigGetCmd() *cobra.Command {
 96→	return &cobra.Command{
 97→		Use:   "get <key>",
 98→		Short: "Get a config value",
 99→		Long:  "Valid keys: " + strings.Join(config.ValidKeys(), ", "),
100→		Args:  cobra.ExactArgs(1),
101→		RunE: func(cmd *cobra.Command, args []string) error {
102→			val, err := config.Get(args[0])
103→			if err != nil {
104→				return err
105→			}
106→			if val == "" {
107→				fmt.Println("(not set)")
108→			} else {
109→				fmt.Println(val)
110→			}
111→			return nil
112→		},
113→	}
114→}
115→
116→func newConfigListCmd() *cobra.Command {
117→	return &cobra.Command{
118→		Use:   "list",
119→		Short: "List all config values",
120→		RunE: func(cmd *cobra.Command, args []string) error {
121→			cfg, err := config.Load("")
122→			if err != nil {
123→				return err
124→			}
125→
126→			fmt.Printf("base_url:  %s\n", maskEmpty(cfg.BaseURL))
127→			fmt.Printf("api_key:   %s\n", maskAPIKey(cfg.APIKey))
128→			fmt.Printf("workspace: %s\n", maskEmpty(cfg.Workspace))
129→			fmt.Printf("project:   %s\n", maskEmpty(cfg.Project))
130→			fmt.Printf("format:    %s\n", maskEmpty(cfg.Format))
131→			fmt.Printf("\nConfig file: %s\n", config.FilePath())
132→			return nil
133→		},
134→	}
135→}
136→
137→func maskAPIKey(key string) string {
138→	if key == "" {
139→		return "(not set)"
140→	}
141→	if len(key) <= 8 {
142→		return "****"
143→	}
144→	return key[:4] + "..." + key[len(key)-4:]
145→}
146→
147→func maskEmpty(s string) string {
148→	if s == "" {
149→		return "(not set)"
150→	}
151→	return s
152→}
