 14→// wrapHTML ensures text is wrapped in <p> tags for Plane's Tiptap editor.
 15→// If the input already contains HTML tags, it's returned as-is.
 16→func wrapHTML(s string) string {
 17→	trimmed := strings.TrimSpace(s)
 18→	if strings.HasPrefix(trimmed, "<") {
 19→		return trimmed
 20→	}
 21→	return "<p>" + trimmed + "</p>"
 22→}
